// The SmartLMS backend posts one content.created event per publish.
const raw = $input.first().json;
const body = raw.body ?? raw;

if (!body || body.event !== 'content.created') {
  throw new Error('Unexpected payload — expected event "content.created"');
}

const recipients = (body.recipients || []).filter((r) => r && r.email);
if (recipients.length === 0) {
  // Nobody enrolled (or nobody has an email) — stop quietly.
  return [];
}

const content = body.content || {};
const course = body.course || {};

// Deadline arrives as an ISO string, or null for items without one.
let deadlineText = 'No deadline set';
if (content.deadline) {
  const d = new Date(content.deadline);
  if (!isNaN(d.getTime())) {
    deadlineText = d.toLocaleString('en-GB', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }
}

return [
  {
    json: {
      kind: body.kind || 'assignment',
      kindLabel: body.kindLabel || 'Assignment',
      title: content.title || 'New coursework',
      description: content.description || '',
      deadline: content.deadline || null,
      deadlineText,
      totalMarks: content.totalMarks || 0,
      link: content.link || '',
      courseTitle: course.title || 'your course',
      instructorName: (body.instructor || {}).name || 'Your instructor',
      recipients,
      recipientCount: recipients.length,
    },
  },
];

