// The LLM node returns its text under a different key depending on version,
// so all the usual ones are tried before falling back to a written sentence.
const ai = $input.first().json || {};
const event = $('Validate & Normalize Event').first().json;

let copy = (ai.text ?? ai.response ?? ai.output ?? ai.content ?? '').toString().trim();

// Models sometimes wrap the answer in a markdown fence.
copy = copy.replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();

if (!copy) {
  copy =
    event.instructorName +
    ' has posted a new ' +
    event.kindLabel.toLowerCase() +
    ' for ' +
    event.courseTitle +
    '. Open SmartLMS to read the brief and submit before the deadline.';
}

return [{ json: { ...event, aiCopy: copy } }];

// One item per student (Split Out ran on `recipients`).
//
// The event fields are read with a fallback to the Capture AI Copy node, so the
// email still fills in correctly even if Split Out is set to drop other fields.
const source = $('Capture AI Copy').first().json;
const roster = Array.isArray(source.recipients) ? source.recipients : [];

const THEME = {
  assignment: { accent: '#4338ca', soft: '#eceafd', label: 'Assignment' },
  quiz:       { accent: '#0f766e', soft: '#dcf5f1', label: 'Quiz' },
  exam:       { accent: '#be123c', soft: '#fbe0e6', label: 'Exam' },
  project:    { accent: '#a1600a', soft: '#fcefd9', label: 'Project' },
};

const esc = (s) =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const pick = (row, key, fallback = '') => {
  const v = row[key] ?? source[key];
  return v === undefined || v === null || v === '' ? fallback : v;
};

return $input.all().map((item, index) => {
  const row = item.json;

  // The recipient can arrive in a few shapes depending on how Split Out is
  // configured (destination field set, "other fields" dropped, etc). Fall back
  // to the roster from the webhook payload, matched by position, so the email
  // address is never lost.
  const fallback = roster[index] || roster[0] || {};
  const nested =
    (row.recipients && typeof row.recipients === 'object' ? row.recipients : null) ||
    (row.recipient && typeof row.recipient === 'object' ? row.recipient : null) ||
    {};

  const email = row.email || row.to || nested.email || fallback.email || '';
  const studentName = row.name || nested.name || fallback.name || '';
  const studentFirst =
    row.first_name || nested.first_name || fallback.first_name || studentName;

  if (!email) {
    throw new Error(
      'No email address for this recipient. Check the Split Out Recipients node — ' +
        'Field to Split Out must be "recipients" and Destination Field Name must be empty.'
    );
  }

  const kind = pick(row, 'kind', 'assignment');
  const theme = THEME[kind] || THEME.assignment;

  const kindLabel = pick(row, 'kindLabel', theme.label);
  const title = pick(row, 'title', 'New coursework');
  const courseTitle = pick(row, 'courseTitle', 'your course');
  const instructorName = pick(row, 'instructorName', 'Your instructor');
  const deadlineText = pick(row, 'deadlineText', 'No deadline set');
  const totalMarks = pick(row, 'totalMarks', 0);
  const link = pick(row, 'link', 'http://localhost:3000/student');
  const aiCopy = pick(
    row,
    'aiCopy',
    `${instructorName} has posted a new ${kindLabel.toLowerCase()} for ${courseTitle}. Open SmartLMS to read the brief and submit before the deadline.`
  );

  const firstName = studentFirst || 'there';
  const subject = `New ${kindLabel}: ${title} — ${courseTitle}`;

  const detailRow = (label, value, strong) => `
        <tr>
          <td style="padding:13px 18px;border-bottom:1px solid #e9ebf4;font-size:12px;color:#6b7092;letter-spacing:.04em;text-transform:uppercase;">${esc(label)}</td>
          <td style="padding:13px 18px;border-bottom:1px solid #e9ebf4;font-size:14px;font-weight:600;text-align:right;color:${strong ? theme.accent : '#12142a'};">${esc(value)}</td>
        </tr>`;

  const html = `
<div style="margin:0;padding:32px 16px;background:#eef0f7;font-family:'Segoe UI',Helvetica,Arial,sans-serif;">
  <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;margin:0 auto;border-collapse:separate;border-spacing:0;background:#ffffff;border-radius:18px;overflow:hidden;box-shadow:0 18px 40px -22px rgba(18,20,42,.45);">

    <!-- header -->
    <tr>
      <td style="background:linear-gradient(135deg,#16183a 0%,#2a2f66 55%,${theme.accent} 100%);padding:26px 32px;">
        <p style="margin:0;color:#ffffff;font-size:17px;font-weight:700;letter-spacing:.14em;">SMARTLMS</p>
        <p style="margin:5px 0 0;color:#b9bde4;font-size:12px;letter-spacing:.02em;">Mari Energies Bootcamp &middot; Xloop Digital</p>
      </td>
    </tr>

    <!-- accent hairline -->
    <tr><td style="height:4px;background:${theme.accent};font-size:0;line-height:0;">&nbsp;</td></tr>

    <!-- body -->
    <tr>
      <td style="padding:32px;">

        <span style="display:inline-block;background:${theme.soft};color:${theme.accent};font-size:11px;font-weight:700;letter-spacing:.1em;padding:6px 13px;border-radius:999px;text-transform:uppercase;">
          New ${esc(kindLabel)}
        </span>

        <h1 style="margin:18px 0 6px;font-size:23px;line-height:1.3;color:#12142a;font-weight:700;">${esc(title)}</h1>
        <p style="margin:0 0 26px;font-size:14px;color:#6b7092;">
          <span style="color:${theme.accent};font-weight:600;">${esc(courseTitle)}</span>
          &nbsp;&middot;&nbsp; ${esc(instructorName)}
        </p>

        <p style="margin:0 0 8px;font-size:15px;color:#12142a;font-weight:600;">Hi ${esc(firstName)},</p>
        <p style="margin:0 0 26px;font-size:15px;line-height:1.7;color:#3a3f60;">${esc(aiCopy)}</p>

        <!-- details -->
        <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:separate;border-spacing:0;background:#f7f8fc;border:1px solid #e2e5f0;border-left:4px solid ${theme.accent};border-radius:12px;overflow:hidden;">
          ${detailRow('Type', kindLabel, false)}
          ${detailRow('Deadline', deadlineText, true)}
          ${detailRow('Total marks', totalMarks, false)}
          <tr>
            <td style="padding:13px 18px;font-size:12px;color:#6b7092;letter-spacing:.04em;text-transform:uppercase;">Instructor</td>
            <td style="padding:13px 18px;font-size:14px;font-weight:600;text-align:right;color:#12142a;">${esc(instructorName)}</td>
          </tr>
        </table>

        <!-- cta -->
        <table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0 6px;">
          <tr>
            <td style="border-radius:11px;background:${theme.accent};box-shadow:0 8px 18px -8px ${theme.accent};">
              <a href="${esc(link)}"
                 style="display:inline-block;padding:14px 30px;color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;letter-spacing:.01em;">
                Open in SmartLMS &nbsp;&rarr;
              </a>
            </td>
          </tr>
        </table>

        <p style="margin:18px 0 0;font-size:12px;color:#8b90ad;line-height:1.6;">
          Trouble with the button? Paste this into your browser:<br>
          <span style="color:${theme.accent};word-break:break-all;">${esc(link)}</span>
        </p>

      </td>
    </tr>

    <!-- footer -->
    <tr>
      <td style="padding:20px 32px;border-top:1px solid #e2e5f0;background:#f7f8fc;">
        <p style="margin:0;font-size:11px;line-height:1.6;color:#8b90ad;">
          Automated message from <strong style="color:#5a5f80;">SmartLMS</strong>. Please don't reply to this email &mdash;
          post your questions on the course page instead.
        </p>
      </td>
    </tr>

  </table>
</div>`.trim();

  return { json: { to: email, studentName, subject, html } };
});
